def compute_a(n, memo):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0

    if n % 2 == 0:
        # n = 2k, k = n // 2
        k = n // 2
        result = 2 * compute_a(k, memo) + k
    else:
        # n = 2k + 1, k = (n - 1) // 2
        k = (n - 1) // 2
        # a_{2k+1} = a_k + a_{k+1} + k
        result = compute_a(k, memo) + compute_a(k + 1, memo) + k

    memo[n] = result
    return result

N = 2025
memo = {}
a_2025 = compute_a(N, memo)
print(a_2025)

def calculate_a(n_max):
    a = {1: 0}
    for n in range(2, n_max + 1):
        max_val = -1
        for i in range(1, n):
            term = a[i] + a[n - i] + min(i, n - i)
            if term > max_val:
                max_val = term
        a[n] = max_val
    return a

a_values = calculate_a(12)
print("Calculated a_n values:")
for n in range(1, 13):
    print(f"a_{n} = {a_values[n]}")

def check_pattern(n_max, a_values):
    print("\nPattern Check: a_n = a_{floor(n/2)} + a_{ceil(n/2)} + floor(n/2)")
    for n in range(2, n_max + 1):
        floor_n_over_2 = n // 2
        ceil_n_over_2 = (n + 1) // 2

        predicted = a_values[floor_n_over_2] + a_values[ceil_n_over_2] + floor_n_over_2
        actual = a_values[n]

        status = "Matches" if predicted == actual else "MISMATCH"
        print(f"n={n}: Predicted={predicted}, Actual={actual} -> {status}")

check_pattern(12, a_values)
